// END GENERATED

const CACHE = `topgrade-${VERSION}`;
const SCOPE = self.registration.scope;
const SHELL = new URL('index.html', SCOPE).href;
const PRECACHED = new Set(FILES.map((f) => new URL(f, SCOPE).href));
// Previews are published under <scope>/preview/ with their own page and worker (or, when none is published,
// the server redirects that address to the live app). Never answer those addresses with this app's page:
// it would not know the /preview/ path and show "page not found".
const PREVIEW = new URL('preview/', SCOPE).href;
// «راسلنا» goes through the server, which opens WhatsApp (the number is kept only there).
const WHATSAPP = new URL('whatsapp', SCOPE).href;
// The owner's notifications page is its own page on the server, not part of the app.
const ADMIN = new URL('admin/', SCOPE).href;
// A preview's worker caches nothing (a reviewer always sees the latest build); it is there for notifications.
const IS_PREVIEW = new URL(SCOPE).pathname.endsWith('/preview/');

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    if (IS_PREVIEW) return self.skipWaiting();
    const cache = await caches.open(CACHE);
    await cache.addAll(FILES.map((f) => new Request(new URL(f, SCOPE).href, { cache: 'reload' })));
    // First install: take over right away. Updates wait for the page to say it is a safe moment.
    if (!self.registration.active) await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    // Caches are shared by the whole site: a preview's worker must never clear the live app's copy.
    if (!IS_PREVIEW) {
      const names = await caches.keys();
      await Promise.all(names.filter((n) => n.startsWith('topgrade-') && n !== CACHE).map((n) => caches.delete(n)));
    }
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting();
});

async function fromCache(url) {
  const cache = await caches.open(CACHE);
  return (await cache.match(url)) ?? fetch(url);
}

// Course data (the course list and question banks) comes from the server first, so a new course or question is
// there on the first open after a deploy, without waiting for the app update to download. The cached copy
// answers when the server is slow (a few seconds) or the phone is offline.
const DATA = new URL('data/', SCOPE).href;
async function fromNetwork(url) {
  const cache = await caches.open(CACHE);
  try {
    const res = await Promise.race([
      fetch(url, { cache: 'no-cache' }),
      new Promise((_, fail) => setTimeout(() => fail(new Error('slow network')), 4000)),
    ]);
    if (res.ok) {
      cache.put(url, res.clone());
      return res;
    }
  } catch {
    /* offline or slow: fall back to the cached copy */
  }
  return (await cache.match(url)) ?? fetch(url);
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (IS_PREVIEW || request.method !== 'GET' || !request.url.startsWith(SCOPE)) return;
  // Every app URL (/, /courses/..., /review) is the same page.
  if (request.mode === 'navigate') {
    if (request.url.startsWith(PREVIEW) || request.url.startsWith(ADMIN) || request.url.split('?')[0] === WHATSAPP) return;
    event.respondWith(fromCache(SHELL));
    return;
  }
  const url = new URL(request.url);
  // ?fresh asks for the server's copy (e.g. the course list, when a link names a course this copy doesn't know yet).
  if (url.searchParams.has('fresh')) return;
  url.search = '';
  if (PRECACHED.has(url.href)) event.respondWith(url.href.startsWith(DATA) ? fromNetwork(url.href) : fromCache(url.href));
  // Anything else (e.g. the link-preview image) goes to the network as usual.
});

/* ---------- Notifications ---------- */

// A notification sent from the owner's page. The message is in the Declarative Web Push shape
// ({ web_push: 8030, notification: { title, body, navigate, tag } }), which Safari shows by itself; other browsers
// get it here. One per course at a time (tag): a newer message about a course replaces the older one.
self.addEventListener('push', (event) => {
  let msg = {};
  try {
    msg = event.data?.json() ?? {};
  } catch {
    msg = { body: event.data?.text() };
  }
  const n = msg.notification || msg;
  event.waitUntil(self.registration.showNotification(n.title || 'Smart Pro | سمارت برو', {
    body: n.body || '',
    // The large picture is a fully transparent image: Android already shows the app's own icon on the left, and with
    // no picture at all Chrome draws a letter circle («S») on the right instead (NotificationBuilderBase.ensureNormalizedIcon).
    icon: new URL('assets/icons/blank-96.png', SCOPE).href,
    badge: new URL('assets/icons/badge-96.png', SCOPE).href,
    tag: n.tag || 'smartpro',
    renotify: true,
    dir: 'auto',
    lang: n.lang || 'ar',
    data: { url: n.navigate || msg.url || SCOPE },
  }));
});

// A tap opens the page the message is about (its link carries ?n=<id>, which the app reports as a tap): in the
// open app if there is one, otherwise a new window.
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const url = event.notification.data?.url;
  const target = url && url.startsWith(SCOPE) ? url : SCOPE;
  event.waitUntil((async () => {
    const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    const open = windows.find((w) => w.url.startsWith(SCOPE));
    if (open) {
      await open.focus();
      return open.navigate(target).catch(() => self.clients.openWindow(target));
    }
    return self.clients.openWindow(target);
  })());
});

// The browser renewed the push address: tell the server, which keeps the student's courses.
self.addEventListener('pushsubscriptionchange', (event) => {
  event.waitUntil((async () => {
    const old = event.oldSubscription;
    const key = old?.options?.applicationServerKey;
    const sub = event.newSubscription || (key && await self.registration.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: key }));
    if (!sub) return;
    await fetch(new URL('api/push/renew', SCOPE).href, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ oldEndpoint: old?.endpoint, subscription: sub.toJSON() }),
    });
  })());
});
